UPDATE exercises SET active=0 WHERE source IN ('opengym','fedb','challenge-gym') AND edited=0;
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0001', '3/4 Sit-Up', 'waist', 'abs', '["hip flexors","lower back"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["3_4_Sit-Up/0.jpg","3_4_Sit-Up/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0002', '45° Side Bend', 'waist', 'abs', '["obliques"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.","Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपकी भुजाएं आपके बगल में सीधी नीचे की ओर फैली हुई हों।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, धीरे-धीरे अपने धड़ को एक तरफ झुकाएं, अपने हाथ को अपने घुटने की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0003', 'Air Bike', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your hands placed behind your head.","Lift your legs off the ground and bend your knees at a 90-degree angle.","Bring your right elbow towards your left knee while simultaneously straightening your right leg.","Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.","Continue alternating sides in a pedaling motion for the desired number of repetitions."]', '["अपने हाथों को अपने सिर के पीछे रखते हुए अपनी पीठ के बल सीधे लेट जाएँ।","अपने पैरों को ज़मीन से ऊपर उठाएं और अपने घुटनों को 90 डिग्री के कोण पर मोड़ें।","अपने दाहिने पैर को सीधा करते हुए अपनी दाहिनी कोहनी को अपने बाएँ घुटने की ओर लाएँ।","प्रारंभिक स्थिति पर लौटें और अपने बाएं पैर को सीधा करते हुए अपनी बाईं कोहनी को अपने दाहिने घुटने की ओर लाते हुए, विपरीत दिशा में आंदोलन को दोहराएं।","पुनरावृत्ति की वांछित संख्या के लिए पैडल गति में पक्षों को बदलना जारी रखें।"]', '["Air_Bike/0.jpg","Air_Bike/1.jpg"]', 7.5, 'sets', 0, 'opengym', 1),
('og-1512', 'All Fours Squad Stretch', 'upper legs', 'quads', '["hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Extend one leg straight back, keeping your knee bent and your foot flexed.","Slowly lower your hips towards the ground, feeling a stretch in your quads.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch on the other side."]', '["अपने हाथों को सीधे अपने कंधों के नीचे और अपने घुटनों को सीधे अपने कूल्हों के नीचे रखकर चारों तरफ से शुरुआत करें।","अपने एक पैर को सीधा पीछे की ओर फैलाएँ, अपने घुटने को मोड़ें और अपने पैर को मोड़ें।","धीरे-धीरे अपने कूल्हों को ज़मीन की ओर नीचे लाएँ, अपने क्वाड्स में खिंचाव महसूस करें।","इस स्थिति में 20-30 सेकंड तक रुकें।","पैरों को बदलें और दूसरी तरफ भी खिंचाव दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0006', 'Alternate Heel Touchers', 'waist', 'abs', '["obliques"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight out to the sides, parallel to the ground.","Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.","Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपनी भुजाओं को ज़मीन के समानांतर, भुजाओं तक सीधा फैलाएँ।","अपने एब्स को शामिल करते हुए, अपने कंधों को ज़मीन से ऊपर उठाएं और अपने दाहिने हाथ को अपनी दाहिनी एड़ी की ओर ले जाएं।","प्रारंभिक स्थिति पर लौटें और बाईं ओर दोहराएं, अपने बाएं हाथ को अपनी बाईं एड़ी तक पहुंचाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', '["Alternate_Heel_Touchers/0.jpg","Alternate_Heel_Touchers/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0007', 'Alternate Lateral Pulldown', 'back', 'lats', '["biceps","rhomboids"]', 'cable', 'strength', NULL, '["Sit on the cable machine with your back straight and feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके केबल मशीन पर बैठें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","थोड़ा पीछे झुकें और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपनी छाती की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1368', 'Ankle Circles', 'lower legs', 'calves', '["ankle stabilizers"]', 'body weight', 'strength', NULL, '["Sit on the ground with your legs extended in front of you.","Lift one leg off the ground and rotate your ankle in a circular motion.","Perform the desired number of circles in one direction, then switch to the other direction.","Repeat with the other leg."]', '["अपने पैरों को सामने फैलाकर जमीन पर बैठें।","एक पैर को जमीन से ऊपर उठाएं और अपने टखने को गोलाकार गति में घुमाएं।","एक दिशा में वांछित संख्या में वृत्त बनाएं, फिर दूसरी दिशा में स्विच करें।","दूसरे पैर से दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3293', 'Archer Pull Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.","Continue pulling until your chin is above the bar and your bent arm is fully flexed.","Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.","Alternate sides with each repetition."]', '["ओवरहैंड ग्रिप के साथ कंधे की चौड़ाई से थोड़ा अधिक चौड़े पुल-अप बार से लटककर शुरुआत करें।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को नीचे और पीछे खींचें।","जैसे ही आप अपने आप को ऊपर खींचते हैं, एक हाथ को मोड़ें और अपनी कोहनी को अपनी तरफ लाएं, जबकि दूसरे हाथ को सीधा रखें।","तब तक खींचते रहें जब तक कि आपकी ठुड्डी बार के ऊपर न आ जाए और आपकी मुड़ी हुई भुजा पूरी तरह से मुड़ न जाए।","अपने आप को नियंत्रण के साथ वापस नीचे लाएँ, मुड़ी हुई भुजा को सीधा करें और दूसरी ओर से भी यही क्रिया दोहराएँ।","प्रत्येक पुनरावृत्ति के साथ वैकल्पिक पक्ष।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3294', 'Archer Push Up', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'body weight', 'strength', NULL, '["Start in a push-up position with your hands slightly wider than shoulder-width apart.","Extend one arm straight out to the side, parallel to the ground.","Lower your body by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position.","Repeat on the other side, extending the opposite arm out to the side.","Continue alternating sides for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखते हुए पुश-अप स्थिति से शुरुआत करें।","एक हाथ को ज़मीन के समानांतर बगल की ओर सीधा फैलाएँ।","अपनी कोहनियों को मोड़कर, अपनी पीठ को सीधा और कोर को व्यस्त रखते हुए अपने शरीर को नीचे लाएँ।","प्रारंभिक स्थिति में वापस पुश करें।","दूसरी ओर दोहराएं, विपरीत भुजा को बगल की ओर फैलाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2355', 'Arm Slingers Hanging Bent Knee Legs', 'waist', 'abs', '["shoulders","back"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.","Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने घुटनों को अपनी छाती की ओर उठाएं, उन्हें जितना संभव हो सके अपनी कोहनी के करीब लाएं।","धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2333', 'Arm Slingers Hanging Straight Legs', 'waist', 'abs', '["shoulders","back"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your legs straight down.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Hold for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपने पैरों को सीधा नीचे करके पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को अपने सामने ऊपर उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं।","एक क्षण के लिए शीर्ष पर रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3214', 'Arms Apart Circular Toe Touch (Male)', 'upper legs', 'glutes', '["hamstrings","quadriceps","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and arms extended to the sides.","Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.","As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.","Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और हाथों को बगल तक फैलाकर खड़े हो जाएं।","अपने पैरों को सीधा रखते हुए, कमर के बल आगे की ओर झुकें और अपने दाहिने हाथ से अपने पैर की उंगलियों तक पहुंचें।","जैसे ही आप नीचे पहुँचते हैं, साथ ही संतुलन बनाए रखते हुए अपने बाएँ पैर को अपने पीछे सीधा ऊपर उठाएँ।","प्रारंभिक स्थिति पर लौटें और अपने बाएं हाथ को अपने पैर की उंगलियों तक पहुंचाते हुए और अपने दाहिने पैर को अपने पीछे ऊपर उठाते हुए इस क्रिया को दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3204', 'Arms Overhead Full Sit-Up (Male)', 'waist', 'abs', '["hip flexors","lower back"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms overhead, keeping them straight.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपनी भुजाओं को सीधा रखते हुए ऊपर की ओर फैलाएँ।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ सीधा न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0009', 'Assisted Chest Dip (Kneeling)', 'chest', 'pectorals', '["triceps","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with your palms facing down and your arms fully extended.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन को अपनी इच्छित ऊंचाई पर समायोजित करें और अपने घुटनों को पैड पर सुरक्षित करें।","अपनी हथेलियों को नीचे की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर हैंडल को पकड़ें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ फर्श के समानांतर न हो जाएँ।","एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0011', 'Assisted Hanging Knee Raise', 'waist', 'abs', '["hip flexors"]', 'assisted', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपनी मुख्य मांसपेशियों को संलग्न करें और अपने घुटनों को अपनी छाती की ओर उठाएं, कूल्हों और घुटनों पर झुकें।","अपने पेट को सिकोड़ते हुए गति के शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0010', 'Assisted Hanging Knee Raise With Throw Down', 'waist', 'abs', '["hip flexors","lower back"]', 'assisted', 'strength', NULL, '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, keeping your legs together.","Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.","Allow your legs to swing back up and repeat the movement for the desired number of repetitions."]', '["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को एक साथ रखते हुए, अपने घुटनों को अपनी छाती की ओर उठाएं।","एक बार जब आपके घुटने छाती के स्तर पर हों, तो अपने पैरों को पूरी तरह फैलाते हुए जमीन की ओर नीचे फेंकें।","अपने पैरों को वापस ऊपर की ओर झुकने दें और वांछित संख्या में दोहराव के लिए इस क्रिया को दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1708', 'Assisted Lying Calves Stretch', 'lower legs', 'calves', '["hamstrings"]', 'assisted', 'strength', NULL, '["Lie on your back with your legs extended.","Bend one knee and place your foot flat on the ground.","Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other leg."]', '["अपने पैरों को फैलाकर अपनी पीठ के बल लेटें।","एक घुटने को मोड़ें और अपने पैर को ज़मीन पर सपाट रखें।","अपने हाथों या तौलिये का उपयोग करके, अपनी पिंडली में खिंचाव महसूस करते हुए, धीरे से अपने पैर की उंगलियों को अपने शरीर की ओर खींचें।","20-30 सेकंड तक खिंचाव बनाए रखें।","खिंचाव छोड़ें और दूसरे पैर पर दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1709', 'Assisted Lying Glutes Stretch', 'upper legs', 'glutes', '["hamstrings"]', 'assisted', 'strength', NULL, '["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."]', '["अपने पैरों को फैलाकर अपनी पीठ के बल लेटें।","अपने दाहिने घुटने को मोड़ें और अपने दाहिने टखने को अपनी बाईं जांघ पर रखें, घुटने के ठीक ऊपर।","अपनी बायीं जांघ को दोनों हाथों से पकड़ें और धीरे से अपनी छाती की ओर खींचें।","20-30 सेकंड तक खिंचाव बनाए रखें।","छोड़ें और दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1710', 'Assisted Lying Gluteus And Piriformis Stretch', 'upper legs', 'glutes', '["hamstrings"]', 'assisted', 'strength', NULL, '["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."]', '["अपने पैरों को फैलाकर अपनी पीठ के बल लेटें।","अपने दाहिने घुटने को मोड़ें और अपने दाहिने टखने को अपनी बाईं जांघ पर रखें, घुटने के ठीक ऊपर।","अपनी बायीं जांघ को दोनों हाथों से पकड़ें और धीरे से अपनी छाती की ओर खींचें।","20-30 सेकंड तक खिंचाव बनाए रखें।","खिंचाव छोड़ें और दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0012', 'Assisted Lying Leg Raise With Lateral Throw Down', 'waist', 'abs', '["hip flexors","obliques"]', 'assisted', 'strength', NULL, '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift your legs off the ground, keeping them straight.","While keeping your legs together, lower them to one side until they are a few inches above the ground.","Pause for a moment, then lift your legs back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपनी पीठ के बल सीधे लेट जाएँ।","समर्थन के लिए अपने हाथों को अपने ग्लूट्स के नीचे रखें।","अपने पेट को संलग्न करें और अपने पैरों को सीधा रखते हुए जमीन से ऊपर उठाएं।","अपने पैरों को एक साथ रखते हुए, उन्हें एक तरफ नीचे करें जब तक कि वे जमीन से कुछ इंच ऊपर न हो जाएं।","एक पल के लिए रुकें, फिर अपने पैरों को वापस प्रारंभिक स्थिति में उठाएं।","इस क्रिया को दूसरी ओर भी दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0013', 'Assisted Lying Leg Raise With Throw Down', 'waist', 'abs', '["hip flexors","quadriceps"]', 'assisted', 'strength', NULL, '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, keeping them straight.","Raise your legs until they are perpendicular to the ground.","Lower your legs back down to the starting position.","Simultaneously, throw your legs down towards the ground, keeping them straight.","Raise your legs back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपनी पीठ के बल सीधे लेट जाएँ।","समर्थन के लिए अपने हाथों को अपने ग्लूट्स के नीचे रखें।","अपने कोर को संलग्न करें और अपने पैरों को सीधा रखते हुए जमीन से ऊपर उठाएं।","अपने पैरों को तब तक उठाएं जब तक वे जमीन से लंबवत न हो जाएं।","अपने पैरों को वापस नीचे प्रारंभिक स्थिति में ले आएँ।","इसके साथ ही अपने पैरों को सीधा रखते हुए नीचे जमीन की ओर फेंकें।","अपने पैरों को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0014', 'Assisted Motion Russian Twist', 'waist', 'abs', '["obliques","lower back"]', 'medicine ball', 'strength', NULL, '["Sit on the ground with your knees bent and feet flat on the floor.","Hold the medicine ball with both hands in front of your chest.","Lean back slightly, engaging your abs and keeping your back straight.","Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को फर्श पर सपाट करके जमीन पर बैठें।","मेडिसिन बॉल को दोनों हाथों से अपनी छाती के सामने पकड़ें।","अपने पेट को जोड़ते हुए और अपनी पीठ को सीधा रखते हुए थोड़ा पीछे झुकें।","धीरे-धीरे अपने धड़ को दाईं ओर मोड़ें, दवा की गेंद को अपने शरीर के दाईं ओर लाएं।","एक पल के लिए रुकें, फिर अपने धड़ को बाईं ओर मोड़ें, दवा की गेंद को अपने शरीर के बाईं ओर लाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0015', 'Assisted Parallel Close Grip Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to your desired weight and height.","Place your hands on the parallel bars with a close grip, palms facing each other.","Hang from the bars with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.","Continue pulling until your chin is above the bars.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन को अपने इच्छित वजन और ऊंचाई के अनुसार समायोजित करें।","अपने हाथों को समानान्तर पट्टियों पर कसकर पकड़ के रखें, हथेलियाँ एक-दूसरे के सामने हों।","अपनी बाहों को पूरी तरह फैलाकर और अपने पैरों को ज़मीन से ऊपर रखते हुए सलाखों से लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए अपने शरीर को सलाखों की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी सलाखों से ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0016', 'Assisted Prone Hamstring', 'upper legs', 'hamstrings', '["glutes","lower back"]', 'assisted', 'strength', NULL, '["Lie face down on a mat or bench with your legs fully extended.","Have a partner or use a resistance band to secure your ankles.","Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को पूरी तरह फैलाकर किसी चटाई या बेंच पर मुंह करके लेट जाएं।","अपनी एड़ियों को सुरक्षित करने के लिए एक साथी रखें या प्रतिरोध बैंड का उपयोग करें।","अपने हैमस्ट्रिंग को संलग्न करें और अपने घुटनों को सीधा रखते हुए अपने पैरों को अपने ग्लूट्स की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1713', 'Assisted Prone Lying Quads Stretch', 'upper legs', 'quads', '["hamstrings","glutes"]', 'assisted', 'strength', NULL, '["Lie face down on the ground with your legs extended.","Bend your left knee and reach back with your left hand to grab your left foot or ankle.","Gently pull your left foot towards your glutes, feeling a stretch in your left quad.","Hold the stretch for 20-30 seconds, then release.","Repeat with your right leg."]', '["अपने पैरों को फैलाकर जमीन पर मुंह करके लेट जाएं।","अपने बाएँ घुटने को मोड़ें और अपने बाएँ हाथ को पीछे ले जाकर अपने बाएँ पैर या टखने को पकड़ें।","अपने बाएँ पैर को धीरे से अपने ग्लूट्स की ओर खींचें, अपने बाएँ क्वाड में खिंचाव महसूस करें।","20-30 सेकंड तक खिंचाव बनाए रखें, फिर छोड़ें।","अपने दाहिने पैर से दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
ON CONFLICT(id) DO UPDATE SET name=excluded.name, body_part=excluded.body_part, target=excluded.target, secondary=excluded.secondary, equipment=excluded.equipment, category=excluded.category, level=excluded.level, instructions=excluded.instructions, instructions_hi=excluded.instructions_hi, images=excluded.images, met=excluded.met, tracking=excluded.tracking, popular=excluded.popular, source=excluded.source, active=excluded.active WHERE exercises.edited=0;
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1714', 'Assisted Prone Rectus Femoris Stretch', 'waist', 'abs', '["quadriceps"]', 'assisted', 'strength', NULL, '["Lie face down on the ground with your legs straight.","Bend your right knee and reach back with your right hand to grab your right foot or ankle.","Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."]', '["अपने पैरों को सीधा करके जमीन पर मुंह करके लेट जाएं।","अपने दाहिने घुटने को मोड़ें और अपने दाहिने पैर या टखने को पकड़ने के लिए अपने दाहिने हाथ से पीछे जाएँ।","अपनी दाहिनी जांघ के सामने खिंचाव महसूस करते हुए धीरे से अपने दाहिने पैर या टखने को अपने ग्लूट्स की ओर खींचें।","20-30 सेकंड तक खिंचाव बनाए रखें।","छोड़ें और दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0017', 'Assisted Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to your desired weight and height settings.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन को अपनी वांछित वजन और ऊंचाई सेटिंग्स के अनुसार समायोजित करें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपने पैरों को ज़मीन से ऊपर रखकर लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए, अपने शरीर को हैंडल की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी हैंडल के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1716', 'Assisted Seated Pectoralis Major Stretch With Stability Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'assisted', 'strength', NULL, '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a stability ball with both hands and extend your arms straight out in front of you.","Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक स्टेबिलिटी बॉल पर बैठें।","दोनों हाथों से एक स्टेबिलिटी बॉल पकड़ें और अपनी भुजाओं को अपने सामने सीधा फैलाएँ।","अपनी पेक्टोरल मांसपेशियों में खिंचाव महसूस करते हुए धीरे-धीरे स्टेबिलिटी बॉल को अपनी छाती की ओर नीचे लाएँ।","कुछ सेकंड के लिए खिंचाव बनाए रखें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1712', 'Assisted Side Lying Adductor Stretch', 'upper legs', 'adductors', '["hamstrings","glutes"]', 'assisted', 'strength', NULL, '["Lie on your side with your legs straight and stacked on top of each other.","Bend your bottom leg slightly for stability.","Place your top foot on a stable surface, such as a bench or step.","Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.","Hold the stretch for 20-30 seconds.","Return to the starting position and repeat on the other side."]', '["अपने पैरों को सीधा और एक दूसरे के ऊपर रखकर करवट से लेटें।","स्थिरता के लिए अपने निचले पैर को थोड़ा मोड़ें।","अपने ऊपरी पैर को किसी स्थिर सतह, जैसे बेंच या सीढ़ी पर रखें।","अपने ऊपरी पैर को सीधा रखते हुए, अपनी आंतरिक जांघ में खिंचाव महसूस करते हुए इसे धीरे-धीरे जमीन की ओर नीचे लाएं।","20-30 सेकंड तक खिंचाव बनाए रखें।","प्रारंभिक स्थिति पर लौटें और दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1758', 'Assisted Sit-Up', 'waist', 'abs', '["hip flexors"]', 'assisted', 'strength', NULL, '["Sit on the edge of a bench or have someone hold your feet down.","Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["किसी बेंच के किनारे पर बैठें या किसी से अपने पैर नीचे रखने को कहें।","अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1431', 'Assisted Standing Chin-Up', 'back', 'lats', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to your desired assistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your chest up and shoulders back, engage your core, and slightly bend your knees.","Pull your body up by flexing your elbows and driving your elbows down towards your sides.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन को अपने इच्छित सहायता स्तर पर समायोजित करें।","फुट प्लेटफॉर्म पर खड़े हो जाएं और हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी छाती को ऊपर और कंधों को पीछे रखें, अपने कोर को संलग्न करें और अपने घुटनों को थोड़ा मोड़ें।","अपनी कोहनियों को मोड़कर और अपनी कोहनियों को अपनी तरफ नीचे की ओर ले जाकर अपने शरीर को ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1432', 'Assisted Standing Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to your desired weight and height settings.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Engage your lats and biceps, and pull yourself up towards the handles.","Pause for a moment at the top, squeezing your back muscles.","Slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन को अपनी वांछित वजन और ऊंचाई सेटिंग्स के अनुसार समायोजित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपने लैट्स और बाइसेप्स को संलग्न करें, और अपने आप को हैंडल की ओर ऊपर खींचें।","अपनी पीठ की मांसपेशियों को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0018', 'Assisted Standing Triceps Extension (With Towel)', 'upper arms', 'triceps', '["shoulders"]', 'assisted', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.","Keep your elbows close to your ears and your upper arms stationary.","Slowly extend your forearms upward, squeezing your triceps at the top.","Pause for a moment, then slowly lower the towel back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों को अपने सिर के पीछे रखकर एक तौलिया पकड़ लें।","अपनी कोहनियों को अपने कानों के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","धीरे-धीरे अपने अग्रबाहुओं को ऊपर की ओर बढ़ाएं, अपने ट्राइसेप्स को शीर्ष पर दबाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे तौलिये को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0019', 'Assisted Triceps Dip (Kneeling)', 'upper arms', 'triceps', '["chest","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to your desired weight and height.","Kneel down on the pad facing the machine, with your hands gripping the handles.","Lower your body by bending your elbows, keeping your back straight and close to the machine.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["मशीन को अपने इच्छित वजन और ऊंचाई के अनुसार समायोजित करें।","मशीन के सामने पैड पर घुटने टेकें, अपने हाथों से हैंडल को पकड़ें।","अपनी कोहनियों को मोड़कर, अपनी पीठ को सीधा और मशीन के पास रखते हुए अपने शरीर को नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2364', 'Assisted Wide-Grip Chest Dip (Kneeling)', 'chest', 'pectorals', '["triceps","shoulders"]', 'leverage machine', 'strength', NULL, '["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with a wide grip and keep your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["मशीन को अपनी इच्छित ऊंचाई पर समायोजित करें और अपने घुटनों को पैड पर सुरक्षित करें।","हैंडल को चौड़ी पकड़ से पकड़ें और अपनी कोहनियों को थोड़ा मोड़कर रखें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ फर्श के समानांतर न हो जाएँ।","अपनी भुजाओं को फैलाकर अपने आप को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3220', 'Astride Jumps (Male)', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves"]', 'body weight', 'cardio', NULL, '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively upwards, extending your legs and arms.","While in the air, spread your legs apart and bring your arms out to the sides.","Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","अपने पैरों और भुजाओं को फैलाते हुए तेजी से ऊपर की ओर कूदें।","हवा में रहते हुए, अपने पैरों को फैलाएं और अपनी भुजाओं को बगल की ओर लाएं।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए, प्रभाव को अवशोषित करने के लिए अपने घुटनों को मोड़ते हुए, धीरे से जमीन पर उतरें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-3672', 'Back And Forth Step', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","glutes","calves"]', 'body weight', 'cardio', NULL, '["Stand with your feet shoulder-width apart.","Step forward with your right foot, bending your knee and lowering your body into a lunge position.","Push off with your right foot and step back to the starting position.","Repeat the movement with your left foot, alternating legs with each step.","Continue stepping back and forth, maintaining a steady pace.","Repeat for the desired duration or number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने दाहिने पैर के साथ आगे बढ़ें, अपने घुटने को मोड़ें और अपने शरीर को एक लंज स्थिति में नीचे लाएँ।","अपने दाहिने पैर से धक्का दें और प्रारंभिक स्थिति में वापस आ जाएँ।","प्रत्येक चरण के साथ पैरों को बारी-बारी से अपने बाएं पैर से दोहराएं।","स्थिर गति बनाए रखते हुए आगे-पीछे कदम बढ़ाते रहें।","वांछित अवधि या दोहराव की संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-1314', 'Back Extension On Exercise Ball', 'back', 'spine', '["glutes","hamstrings"]', 'stability ball', 'strength', NULL, '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल को जमीन पर रखें और उसके ऊपर मुंह करके लेट जाएं, अपने कूल्हों को बॉल पर और अपने पैरों को दीवार या अन्य स्थिर सतह पर टिकाएं।","अपने हाथों को अपने सिर के पीछे रखें या अपनी छाती के ऊपर रखें।","अपने कोर को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को गेंद से ऊपर उठाएं, अपनी पीठ को तब तक फैलाएं जब तक कि आपका शरीर आपके सिर से आपकी एड़ी तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3297', 'Back Lever', 'back', 'upper back', '["biceps","forearms","core"]', 'body weight', 'strength', NULL, '["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.","Hold this position for a few seconds, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["ओवरहैंड पकड़ के साथ पुल-अप बार से लटकने से शुरुआत करें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को नीचे और पीछे खींचें।","अपने घुटनों को मोड़ें और उन्हें अपनी छाती की ओर मोड़ें।","धीरे-धीरे अपने पैरों को ऊपर उठाएं, उन्हें सीधा रखें, जब तक कि आपका शरीर जमीन के समानांतर न हो जाए।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1405', 'Back Pec Stretch', 'back', 'lats', '["shoulders","chest"]', 'body weight', 'strength', NULL, '["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you, parallel to the ground.","Cross your arms in front of your body, with your right arm over your left arm.","Interlock your fingers and rotate your palms away from your body.","Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.","Hold the stretch for 15-30 seconds, then release.","Repeat on the opposite side."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े रहें।","अपनी भुजाओं को ज़मीन के समानांतर, अपने सामने सीधा फैलाएँ।","अपनी भुजाओं को अपने शरीर के सामने क्रॉस करें, अपनी दायीं भुजा को अपनी बायीं भुजा के ऊपर रखें।","अपनी उंगलियों को आपस में फंसा लें और अपनी हथेलियों को अपने शरीर से दूर घुमाएं।","अपनी पीठ और छाती में खिंचाव महसूस करते हुए धीरे-धीरे अपनी बाहों को ऊपर और अपने शरीर से दूर उठाएं।","15-30 सेकंड तक खिंचाव बनाए रखें, फिर छोड़ें।","विपरीत दिशा में दोहराएँ."]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1473', 'Backward Jump', 'upper legs', 'quads', '["hamstrings","glutes","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump backwards, pushing off with both feet.","Land softly on the balls of your feet, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को थोड़ा मोड़ें और दोनों पैरों से धक्का देते हुए पीछे की ओर कूदें।","प्रभाव को अवशोषित करने के लिए अपने घुटनों को मोड़ते हुए, अपने पैरों की उंगलियों पर धीरे से उतरें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0020', 'Balance Board', 'upper legs', 'quads', '["calves","hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Place the balance board on a flat surface.","Step onto the balance board with one foot, ensuring it is centered.","Slowly shift your weight onto the foot on the balance board, keeping your core engaged.","Maintain your balance and stability as you hold the position for a desired amount of time.","Repeat the exercise with the other foot."]', '["बैलेंस बोर्ड को समतल सतह पर रखें।","एक पैर से बैलेंस बोर्ड पर कदम रखें, यह सुनिश्चित करते हुए कि यह बीच में है।","अपने कोर को व्यस्त रखते हुए धीरे-धीरे अपना वजन बैलेंस बोर्ड पर पैर पर डालें।","वांछित समय तक पद पर रहते हुए अपना संतुलन और स्थिरता बनाए रखें।","दूसरे पैर से भी व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0968', 'Band Alternating Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.","Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.","Lower the arm back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को हाथ से पकड़ें, हथेलियाँ ऊपर की ओर हों।","अपनी कोहनियों को अपने किनारों के पास रखें और धीरे-धीरे एक हाथ को अपने कंधे की ओर मोड़ें, अपने बाइसेप्स को ऊपर की ओर दबाएं।","हाथ को वापस प्रारंभिक स्थिति में लाएँ और दूसरे हाथ से दोहराएँ।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0969', 'Band Alternating V-Up', 'waist', 'abs', '["hip flexors"]', 'band', 'strength', NULL, '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.","Repeat the movement, alternating the position of your legs with each repetition.","Continue for the desired number of repetitions."]', '["अपने पैरों को सीधा करके और अपनी बाहों को ऊपर की ओर फैलाकर, बैंड को पकड़कर अपनी पीठ के बल लेट जाएँ।","अपने पेट को संलग्न करें और अपने पैरों और शरीर के ऊपरी हिस्से को एक साथ जमीन से ऊपर उठाएं, अपने हाथों को अपने पैर की उंगलियों तक पहुंचाएं।","जैसे ही आप अपने पैरों और ऊपरी शरीर को वापस नीचे लाते हैं, एक को दूसरे के ऊपर रखते हुए अपने पैरों की स्थिति बदलें।","प्रत्येक पुनरावृत्ति के साथ अपने पैरों की स्थिति को बदलते हुए, आंदोलन को दोहराएं।","दोहराव की वांछित संख्या के लिए जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0970', 'Band Assisted Pull-Up', 'back', 'lats', '["biceps","forearms"]', 'band', 'strength', NULL, '["Attach the band to a pull-up bar or sturdy anchor point.","Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.","Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["बैंड को पुल-अप बार या मजबूत एंकर पॉइंट से जोड़ें।","बैंड पर कदम रखें और अपनी हथेलियों को अपने से दूर रखते हुए बार को पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी बाहों को पूरी तरह फैलाकर लटकें, अपने कोर को व्यस्त रखें और अपने कंधों को नीचे और पीछे रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़कर और अपनी कोहनियों को अपने कूल्हों की ओर ले जाकर अपने शरीर को बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक कि आपकी ठुड्डी बार के ऊपर न आ जाए, फिर धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0971', 'Band Assisted Wheel Rollerout', 'waist', 'abs', '["lower back"]', 'band', 'strength', NULL, '["Kneel on the floor and hold the handles of the band with both hands, palms facing down.","Place the band on the ground in front of you and position your hands shoulder-width apart.","Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.","Repeat for the desired number of repetitions."]', '["फर्श पर घुटने टेकें और बैंड के हैंडल को दोनों हाथों से पकड़ें, हथेलियाँ नीचे की ओर हों।","बैंड को अपने सामने ज़मीन पर रखें और अपने हाथों को कंधे की चौड़ाई से अलग रखें।","अपने कोर को संलग्न करें और धीरे-धीरे पहिया को आगे की ओर घुमाएं, नियंत्रण बनाए रखते हुए अपने शरीर को जितना हो सके उतना फैलाएं।","सबसे दूर वाले बिंदु पर एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए धीरे-धीरे पहिये को अपने घुटनों की ओर घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1254', 'Band Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'band', 'strength', 'beginner', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, pushing the bands away from your chest.","Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बैंड के हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को पूरी तरह फैलाएं, बैंड को अपनी छाती से दूर धकेलें।","अपनी कोहनियों को 90 डिग्री के कोण पर रखते हुए, बैंड को धीरे-धीरे वापस अपनी छाती तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Bench_Press_-_With_Bands/0.jpg","Bench_Press_-_With_Bands/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0980', 'Band Bent-Over Hip Extension', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'band', 'strength', NULL, '["Attach the band to a sturdy anchor point at ankle height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step back to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and lean forward, maintaining a neutral spine.","Extend your right leg straight back, squeezing your glutes at the top.","Lower your right leg back down and repeat with the left leg.","Continue alternating legs for the desired number of repetitions."]', '["बैंड को टखने की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट से दूर की ओर मुंह करके खड़े हो जाएं।","बैंड में तनाव पैदा करने के लिए अपने घुटनों को थोड़ा मोड़कर पीछे हटें।","कूल्हों पर टिकाएं और तटस्थ रीढ़ बनाए रखते हुए आगे की ओर झुकें।","अपने दाहिने पैर को सीधा पीछे की ओर फैलाएँ, अपने ग्लूट्स को ऊपर की ओर दबाएँ।","अपने दाहिने पैर को वापस नीचे लाएँ और बाएँ पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0972', 'Band Bicycle Crunch', 'waist', 'abs', '["hip flexors","obliques"]', 'band', 'strength', NULL, '["Lie flat on your back with your hands behind your head and your knees bent.","Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.","Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.","Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.","Repeat for the desired number of repetitions."]', '["अपने हाथों को अपने सिर के पीछे रखते हुए और अपने घुटनों को मोड़कर अपनी पीठ के बल सीधे लेट जाएँ।","अपने पैरों को जमीन से ऊपर उठाएं और अपने दाहिने घुटने को अपनी छाती की ओर लाएं, साथ ही अपने धड़ को मोड़कर अपनी बाईं कोहनी को अपने दाहिने घुटने की ओर लाएं।","अपने बाएं घुटने को अपनी छाती की ओर लाते हुए अपने दाहिने पैर को सीधा करें और अपनी दाहिनी कोहनी को अपने बाएं घुटने की ओर लाने के लिए अपने धड़ को मोड़ें।","घुमाव की गति को बारी-बारी से जारी रखें, जैसे कि आप साइकिल को पैडल चला रहे हों, जबकि पूरे आंदोलन के दौरान अपने कोर को व्यस्त रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 7.5, 'sets', 0, 'opengym', 1),
('og-0974', 'Band Close-Grip Pulldown', 'back', 'lats', '["biceps","forearms"]', 'band', 'strength', NULL, '["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.","Step back to create tension in the band, keeping your feet hip-width apart.","Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions."]', '["बैंड को किसी ऊंचे एंकर बिंदु, जैसे पुल-अप बार या मजबूत बीम से जोड़ें।","एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं और हाथों को कंधे की चौड़ाई से अलग रखते हुए बैंड को अंडरहैंड ग्रिप से पकड़ें।","अपने पैरों को कूल्हे की चौड़ाई से अलग रखते हुए, बैंड में तनाव पैदा करने के लिए पीछे हटें।","अपने कोर को संलग्न करें और अपनी पीठ को सीधा रखें क्योंकि आप बैंड को अपनी छाती की ओर खींचते हैं, अपने कंधे के ब्लेड को एक साथ निचोड़ते हैं।","आंदोलन के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
ON CONFLICT(id) DO UPDATE SET name=excluded.name, body_part=excluded.body_part, target=excluded.target, secondary=excluded.secondary, equipment=excluded.equipment, category=excluded.category, level=excluded.level, instructions=excluded.instructions, instructions_hi=excluded.instructions_hi, images=excluded.images, met=excluded.met, tracking=excluded.tracking, popular=excluded.popular, source=excluded.source, active=excluded.active WHERE exercises.edited=0;
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0975', 'Band Close-Grip Push-Up', 'upper arms', 'triceps', '["chest","shoulders"]', 'band', 'strength', NULL, '["Place a band around your upper arms, just above the elbows.","Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी ऊपरी भुजाओं के चारों ओर, कोहनियों के ठीक ऊपर एक बैंड रखें।","अपने हाथों को सीधे अपने कंधों के नीचे और अपने शरीर को सिर से एड़ी तक एक सीधी रेखा में रखते हुए पुश-अप स्थिति लें।","अपनी कोहनियों को मोड़ें और अपनी छाती को ज़मीन की ओर नीचे करें, अपनी कोहनियों को अपनी भुजाओं के पास रखें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0976', 'Band Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'band', 'strength', NULL, '["Sit on a bench or chair with your legs spread apart and your feet flat on the ground.","Hold one end of the band in your hand and step on the other end with your foot on the same side.","Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.","With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower your hand back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को फैलाकर एक बेंच या कुर्सी पर बैठें और आपके पैर जमीन पर सपाट हों।","बैंड के एक सिरे को अपने हाथ में पकड़ें और अपने पैर को उसी तरफ रखते हुए दूसरे सिरे पर कदम रखें।","थोड़ा आगे झुकें और अपनी कोहनी को घुटने के ठीक ऊपर, अपनी जांघ के अंदर पर टिकाएं।","अपनी हथेली को ऊपर की ओर रखते हुए, धीरे-धीरे अपने हाथ को अपने कंधे की ओर मोड़ें, अपनी ऊपरी भुजा को स्थिर रखें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने हाथ को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3117', 'Band Fixed Back Close Grip Pulldown', 'back', 'lats', '["biceps","forearms"]', 'band', 'strength', NULL, '["Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.","Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.","Grasp the band with a close grip, palms facing towards you.","Keep your back straight and engage your core.","Pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the band back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', '["बैंड को अपने ऊपर एक निश्चित बिंदु पर संलग्न करें, जैसे कि पुल-अप बार या मजबूत बीम।","बैंड के सामने एक बेंच या कुर्सी पर बैठें, आपके पैर ज़मीन पर सपाट हों और आपके घुटने मुड़े हुए हों।","बैंड को ज़ोर से पकड़ें, हथेलियाँ आपकी ओर हों।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपने कंधे के ब्लेड को एक साथ दबाते हुए, बैंड को अपनी छाती की ओर नीचे खींचें।","गति के निचले भाग में एक पल के लिए रुकें, अपने लैट्स में संकुचन महसूस करें।","पूरे आंदोलन पर नियंत्रण बनाए रखते हुए, बैंड को धीरे-धीरे प्रारंभिक स्थिति में वापस छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3116', 'Band Fixed Back Underhand Pulldown', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'band', 'strength', NULL, '["Attach the band to a sturdy anchor point above your head.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Step back to create tension in the band, keeping your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull the band down towards your chest, leading with your elbows.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions."]', '["बैंड को अपने सिर के ऊपर एक मजबूत एंकर पॉइंट से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं।","बैंड को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी बाहों को पूरी तरह फैलाए रखते हुए बैंड में तनाव पैदा करने के लिए पीछे हटें।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को एक साथ निचोड़ें।","बैंड को अपनी कोहनियों से आगे बढ़ाते हुए अपनी छाती की ओर नीचे खींचें।","गति के निचले भाग में एक पल के लिए रुकें, अपने लैट्स में संकुचन महसूस करें।","धीरे-धीरे बैंड में तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0977', 'Band Front Lateral Raise', 'shoulders', 'delts', '["traps","upper back"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the band back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी हथेलियों को नीचे की ओर रखते हुए बैंड को अपनी जांघों के सामने पकड़ें।","अपनी भुजाओं को सीधा रखें और बैंड को अपने सामने तब तक ऊपर उठाएं जब तक कि आपकी भुजाएं जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0978', 'Band Front Raise', 'shoulders', 'delts', '["triceps","upper back"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and slowly raise them forward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी हथेलियों को नीचे की ओर रखते हुए बैंड को अपनी जांघों के सामने पकड़ें।","अपनी भुजाओं को सीधा रखें और धीरे-धीरे उन्हें आगे की ओर उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1408', 'Band Hip Lift', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'band', 'strength', 'beginner', '["Lie on your back with your knees bent and feet flat on the ground.","Place a resistance band just above your knees.","Engage your glutes and core muscles.","Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेटें।","अपने घुटनों के ठीक ऊपर एक प्रतिरोध बैंड रखें।","अपने ग्लूट्स और कोर मांसपेशियों को संलग्न करें।","अपनी एड़ियों को ज़मीन पर दबाएँ और अपने कूल्हों को ज़मीन से ऊपर उठाएँ, अपने ग्लूट्स को ऊपर की ओर दबाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Hip_Lift_with_Band/0.jpg","Hip_Lift_with_Band/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0979', 'Band Horizontal Pallof Press', 'waist', 'abs', '["obliques","glutes"]', 'band', 'strength', NULL, '["Attach the band to a sturdy anchor point at waist height.","Stand perpendicular to the anchor point with your feet shoulder-width apart.","Grasp the band handle with both hands and step away from the anchor point to create tension in the band.","Bring your hands to your chest, keeping your elbows bent and close to your body.","Engage your core and maintain a stable stance.","Extend your arms straight out in front of you, pushing the band away from your body.","Hold the extended position for a few seconds, focusing on maintaining tension in your core.","Slowly bring your hands back to your chest, resisting the pull of the band.","Repeat for the desired number of repetitions."]', '["बैंड को कमर की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए लंगर बिंदु पर लंबवत खड़े रहें।","बैंड के हैंडल को दोनों हाथों से पकड़ें और बैंड में तनाव पैदा करने के लिए एंकर पॉइंट से दूर हट जाएं।","अपने हाथों को अपनी छाती के पास लाएँ, अपनी कोहनियाँ मुड़ी हुई और अपने शरीर के पास रखें।","अपने मूल को संलग्न करें और स्थिर रुख बनाए रखें।","अपनी बाहों को अपने सामने सीधा फैलाएं, बैंड को अपने शरीर से दूर धकेलें।","अपने कोर में तनाव बनाए रखने पर ध्यान केंद्रित करते हुए, कुछ सेकंड के लिए विस्तारित स्थिति में रहें।","बैंड के खिंचाव का विरोध करते हुए धीरे-धीरे अपने हाथों को अपनी छाती पर वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0981', 'Band Jack Knife Sit-Up', 'waist', 'abs', '["hip flexors"]', 'band', 'strength', NULL, '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सीधा करके और अपनी बाहों को ऊपर की ओर फैलाकर, बैंड को पकड़कर अपनी पीठ के बल लेट जाएँ।","अपने पेट को संलग्न करें और अपने पैरों और ऊपरी शरीर को एक साथ उठाएं, अपने हाथों को अपने पैरों की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों और शरीर के ऊपरी हिस्से को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0983', 'Band Kneeling One Arm Pulldown', 'back', 'lats', '["biceps","rhomboids"]', 'band', 'strength', NULL, '["Attach the band to a sturdy anchor point above your head.","Kneel down and hold the band with one hand, palm facing down.","Extend your arm fully overhead, keeping your elbow slightly bent.","Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["बैंड को अपने सिर के ऊपर एक मजबूत एंकर पॉइंट से जोड़ें।","घुटने टेकें और बैंड को एक हाथ से पकड़ें, हथेली नीचे की ओर।","अपनी बांह को पूरी तरह ऊपर की ओर फैलाएं, अपनी कोहनी को थोड़ा मोड़कर रखें।","अपनी अंडकोश की मांसपेशियों को संलग्न करें और बैंड को अपनी तरफ नीचे खींचें, अपनी कोहनी को अपनी पसली की ओर लाएं।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0985', 'Band Kneeling Twisting Crunch', 'waist', 'abs', '["obliques"]', 'band', 'strength', NULL, '["Attach the band to a sturdy anchor point at waist height.","Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.","Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.","Pause for a moment, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["बैंड को कमर की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","एंकर बिंदु से दूर की ओर मुंह करके घुटने टेकें और दोनों हाथों से बैंड को पकड़ें, अपनी कोहनियों को मोड़कर अपनी भुजाओं के करीब रखें।","अपने पेट को संलग्न करें और धीरे-धीरे अपने धड़ को एक तरफ मोड़ें, अपने हाथों को अपने विपरीत कूल्हे की ओर लाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0984', 'Band Lying Hip Internal Rotation', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'band', 'strength', NULL, '["Lie on your back with your legs straight and a resistance band looped around your feet.","Bend your knees and bring them towards your chest, keeping your feet together.","Slowly rotate your knees outwards, away from each other, while keeping your feet together.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सीधा करके अपनी पीठ के बल लेटें और आपके पैरों के चारों ओर एक प्रतिरोध बैंड बंधा हुआ हो।","अपने घुटनों को मोड़ें और अपने पैरों को एक साथ रखते हुए उन्हें अपनी छाती की ओर लाएँ।","अपने पैरों को एक साथ रखते हुए धीरे-धीरे अपने घुटनों को एक-दूसरे से दूर बाहर की ओर घुमाएं।","घूर्णन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1002', 'Band Lying Straight Leg Raise', 'waist', 'abs', '["hip flexors"]', 'band', 'strength', NULL, '["Lie flat on your back with your legs straight and your feet together.","Place the band around the arches of your feet and hold the ends of the band with your hands.","Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ के बल लेट जाएं और अपने पैरों को सीधा रखें और पैरों को एक साथ रखें।","बैंड को अपने पैरों के आर्च के चारों ओर रखें और बैंड के सिरों को अपने हाथों से पकड़ें।","अपने पेट को संलग्न करते हुए, दोनों पैरों को जमीन से ऊपर उठाएं जब तक कि वे फर्श से लंबवत न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0986', 'Band One Arm Overhead Biceps Curl', 'upper arms', 'biceps', '["forearms","shoulders"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and place one end of the band under your foot.","Hold the other end of the band with your arm fully extended overhead, palm facing forward.","Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.","Pause for a moment at the top, then slowly lower your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड के एक सिरे को अपने पैर के नीचे रखें।","बैंड के दूसरे सिरे को अपने हाथ से पूरी तरह ऊपर की ओर फैलाकर पकड़ें, हथेली आगे की ओर हो।","अपनी ऊपरी भुजा को स्थिर रखते हुए, अपने अग्रबाहु को अपने कंधे की ओर मोड़ें, अपने बाइसेप्स को निचोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी बांह को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0987', 'Band One Arm Single Leg Split Squat', 'upper legs', 'quads', '["glutes","hamstrings"]', 'band', 'strength', NULL, '["Stand with your feet hip-width apart and place a resistance band around your ankles.","Extend one leg forward and rest the top of your foot on a bench or step behind you.","Hold onto a support with one hand for balance.","Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े हो जाएं और अपनी एड़ियों के चारों ओर एक प्रतिरोध बैंड लगाएं।","एक पैर को आगे बढ़ाएं और अपने पैर के ऊपरी हिस्से को अपने पीछे एक बेंच या स्टेप पर रखें।","संतुलन के लिए एक हाथ से किसी सहारे को पकड़ें।","अपने खड़े पैर को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएं, अपने घुटने को अपने पैर की उंगलियों के अनुरूप रखें।","प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ी को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0988', 'Band One Arm Standing Low Row', 'back', 'upper back', '["biceps","shoulders"]', 'band', 'strength', NULL, '["Attach the band to a stable anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band with one hand, palm facing inward, and step back to create tension in the band.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["बैंड को कमर की ऊंचाई पर एक स्थिर लंगर बिंदु पर संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं।","बैंड को एक हाथ से पकड़ें, हथेली अंदर की ओर रखें और बैंड में तनाव पैदा करने के लिए पीछे हटें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बैंड को अपनी कमर की ओर खींचें।","आंदोलन के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0989', 'Band One Arm Twisting Chest Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'band', 'strength', NULL, '["Attach the band to a sturdy anchor point at chest height.","Stand with your side facing the anchor point and grab the band with one hand.","Step away from the anchor point to create tension in the band.","Position your feet shoulder-width apart and slightly bend your knees.","Bring your hand holding the band across your body, towards the opposite shoulder.","While maintaining tension in the band, push your hand forward and away from your body, extending your arm.","Slowly return to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other hand."]', '["बैंड को छाती की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","एंकर प्वाइंट की ओर मुंह करके खड़े हो जाएं और एक हाथ से बैंड को पकड़ लें।","बैंड में तनाव पैदा करने के लिए एंकर बिंदु से दूर हट जाएं।","अपने पैरों को कंधे की चौड़ाई से अलग रखें और अपने घुटनों को थोड़ा मोड़ लें।","बैंड को पकड़ने वाले अपने हाथ को अपने शरीर के पार, विपरीत कंधे की ओर लाएँ।","बैंड में तनाव बनाए रखते हुए, अपने हाथ को आगे बढ़ाते हुए अपने हाथ को अपने शरीर से दूर और आगे की ओर धकेलें।","धीरे-धीरे प्रारंभिक स्थिति में लौटें और वांछित संख्या में दोहराव के लिए दोहराएं।","करवट बदलें और दूसरे हाथ से व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0990', 'Band One Arm Twisting Seated Row', 'back', 'upper back', '["biceps","shoulders"]', 'band', 'strength', NULL, '["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold the band with one hand and extend your arm fully in front of you.","Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.","At the same time, twist your torso towards the side of the pulling arm.","Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपनी पीठ सीधी करके एक बेंच या कुर्सी पर बैठें।","बैंड को एक हाथ से पकड़ें और अपना हाथ पूरी तरह अपने सामने फैलाएँ।","अपनी पीठ को सीधा रखते हुए, अपनी कोहनी को मोड़कर और अपने कंधे के ब्लेड को एक साथ दबाकर बैंड को अपने शरीर की ओर खींचें।","साथ ही, अपने धड़ को खींचने वाले हाथ की तरफ मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड में तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0991', 'Band Pull Through', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'band', 'strength', NULL, '["Attach a resistance band to a sturdy anchor point at ground level.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step forward to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Drive your hips forward and squeeze your glutes to return to the starting position.","Repeat for the desired number of repetitions."]', '["जमीनी स्तर पर एक मजबूत लंगर बिंदु पर एक प्रतिरोध बैंड संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट से दूर की ओर मुंह करके खड़े हो जाएं।","अपने घुटनों को थोड़ा मुड़ा हुआ रखते हुए, बैंड में तनाव पैदा करने के लिए आगे बढ़ें।","कूल्हों पर झुकें और अपने घुटनों को हल्का सा मोड़ते हुए अपने ग्लूट्स को पीछे धकेलें।","अपने धड़ को तब तक नीचे करें जब तक वह ज़मीन के समानांतर न हो जाए, अपनी हैमस्ट्रिंग में खिंचाव महसूस करें।","अपने कूल्हों को आगे की ओर ले जाएँ और प्रारंभिक स्थिति में लौटने के लिए अपने ग्लूट्स को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0992', 'Band Push Sit-Up', 'waist', 'abs', '["shoulders","chest"]', 'band', 'strength', NULL, '["Attach the band securely to a stable anchor point.","Lie flat on your back with your knees bent and feet flat on the ground.","Hold the band with both hands and extend your arms straight up towards the ceiling.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["बैंड को एक स्थिर एंकर बिंदु पर सुरक्षित रूप से संलग्न करें।","अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","बैंड को दोनों हाथों से पकड़ें और अपनी बाहों को छत की ओर सीधा ऊपर उठाएं।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0993', 'Band Reverse Fly', 'shoulders', 'delts', '["upper back","trapezius"]', 'band', 'strength', NULL, '["Attach the band to a stationary object at chest height.","Stand with your feet shoulder-width apart and hold the band with both hands in front of you.","Keep your arms straight and lift them out to the sides until they are parallel to the ground.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["बैंड को छाती की ऊंचाई पर किसी स्थिर वस्तु से जोड़ें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों से बैंड को अपने सामने पकड़ लें।","अपनी भुजाओं को सीधा रखें और उन्हें बगल की ओर तब तक उठाएँ जब तक वे ज़मीन के समानांतर न हो जाएँ।","आंदोलन के शीर्ष पर अपने कंधे के ब्लेड को एक साथ निचोड़ें।","धीरे-धीरे अपनी भुजाओं को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0994', 'Band Reverse Wrist Curl', 'lower arms', 'forearms', '["forearms"]', 'band', 'strength', NULL, '["Sit on a bench or chair with your feet flat on the ground.","Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें।","बैंड को ऊपरी पकड़ से पकड़ें, हथेलियाँ नीचे की ओर हों, और इसे अपनी उंगलियों के चारों ओर लपेटें।","अपनी कलाईयों को किनारे से लटकाते हुए अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, अपने अग्रबाहुओं को निचोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाइयों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0996', 'Band Seated Hip Internal Rotation', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'band', 'strength', NULL, '["Sit on a chair or bench with your back straight and feet flat on the ground.","Place a resistance band around your thighs, just above your knees.","Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.","Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके कुर्सी या बेंच पर बैठें।","अपने घुटनों के ठीक ऊपर, अपनी जांघों के चारों ओर एक प्रतिरोध बैंड लगाएं।","अपने घुटनों को 90 डिग्री के कोण पर मोड़ें और अपने पैरों को कंधे की चौड़ाई से अलग रखें।","अपने ग्लूट्स को संलग्न करें और बैंड के प्रतिरोध के विरुद्ध दबाव डालते हुए धीरे-धीरे अपने घुटनों को बाहर की ओर घुमाएँ।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1011', 'Band Seated Twist', 'waist', 'abs', '["obliques"]', 'band', 'strength', NULL, '["Sit on the ground with your legs extended in front of you and your back straight.","Wrap the band around your waist and hold the ends with both hands.","Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को अपने सामने फैलाकर और अपनी पीठ को सीधा करके जमीन पर बैठें।","बैंड को अपनी कमर के चारों ओर लपेटें और सिरों को दोनों हाथों से पकड़ें।","अपने पेट को संलग्न करें और धीरे-धीरे अपने धड़ को एक तरफ मोड़ें, अपनी पीठ को सीधा रखें और अपने पैरों को जमीन पर रखें।","मोड़ के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ मोड़ को दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0997', 'Band Shoulder Press', 'shoulders', 'delts', '["triceps","upper back"]', 'band', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.","Press the band overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the band back to shoulder height.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपने पैरों के नीचे रखें।","अपनी हथेलियों को आगे की ओर रखते हुए बैंड को पकड़ें और अपने हाथों को कंधे की ऊंचाई तक उठाएं, कोहनियां मुड़ी हुई हों।","अपनी बाहों को पूरी तरह फैलाते हुए बैंड को ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड को वापस कंधे की ऊंचाई तक ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Shoulder_Press_-_With_Bands/0.jpg","Shoulder_Press_-_With_Bands/1.jpg"]', 5, 'sets', 0, 'opengym', 1)
ON CONFLICT(id) DO UPDATE SET name=excluded.name, body_part=excluded.body_part, target=excluded.target, secondary=excluded.secondary, equipment=excluded.equipment, category=excluded.category, level=excluded.level, instructions=excluded.instructions, instructions_hi=excluded.instructions_hi, images=excluded.images, met=excluded.met, tracking=excluded.tracking, popular=excluded.popular, source=excluded.source, active=excluded.active WHERE exercises.edited=0;
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1018', 'Band Shrug', 'back', 'traps', '["shoulders"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.","Keep your arms straight and relaxed, and let the band hang in front of your thighs.","Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं और बैंड को अपने पैरों के नीचे रखें, अपने हाथों से सिरों को पकड़ें।","अपनी भुजाओं को सीधा और शिथिल रखें और बैंड को अपनी जांघों के सामने लटका रहने दें।","अपने कंधों को ऊपर की ओर झुकाकर, बैंड को जितना संभव हो उतना ऊपर उठाकर अपने जाल को संलग्न करें।","एक क्षण के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0998', 'Band Side Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.","Extend your arms straight out to the sides, keeping them parallel to the ground.","Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.","Pause for a moment, then slowly extend your arms back out to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को दोनों हाथों से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी भुजाओं को ज़मीन के समानांतर रखते हुए, भुजाओं तक सीधा फैलाएँ।","धीरे-धीरे अपनी कोहनियों को मोड़ें और अपने हाथों को अपने कंधों की ओर लाएं, अपनी ऊपरी भुजाओं को स्थिर रखें।","एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0999', 'Band Single Leg Calf Raise', 'lower legs', 'calves', '["ankles","feet"]', 'band', 'strength', NULL, '["Stand with your feet hip-width apart and place the band around the ball of your left foot.","Hold onto a stable object for balance if needed.","Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your left heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the right leg."]', '["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े हो जाएं और बैंड को अपने बाएं पैर की गेंद के चारों ओर रखें।","यदि आवश्यक हो तो संतुलन के लिए किसी स्थिर वस्तु को पकड़ें।","धीरे-धीरे अपनी बायीं एड़ी को जमीन से ऊपर उठाएं, अपने शरीर का वजन अपने पैर की गेंद पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी बायीं एड़ी को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दाहिने पैर पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1000', 'Band Single Leg Reverse Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'band', 'strength', NULL, '["Stand with your feet hip-width apart and place the band around the ball of your foot.","Hold onto a stable object for balance.","Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."]', '["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े हो जाएं और बैंड को अपने पैर की गेंद के चारों ओर रखें।","संतुलन के लिए किसी स्थिर वस्तु को पकड़ें।","धीरे-धीरे अपनी एड़ी को जमीन से ऊपर उठाएं, अपने शरीर का वजन अपने पैर की गेंद पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ, फिर दूसरे चरण पर जाएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1001', 'Band Single Leg Split Squat', 'upper legs', 'quads', '["glutes","hamstrings"]', 'band', 'strength', NULL, '["Stand with your feet hip-width apart and place a resistance band around your ankles.","Take a big step forward with your right foot and a smaller step back with your left foot.","Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.","Push through your right heel to return to the starting position.","Repeat on the other side."]', '["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े हो जाएं और अपनी एड़ियों के चारों ओर एक प्रतिरोध बैंड लगाएं।","अपने दाहिने पैर से एक बड़ा कदम आगे बढ़ाएं और अपने बाएं पैर से एक छोटा कदम पीछे लें।","अपने घुटनों को मोड़ें और अपने शरीर को तब तक नीचे रखें जब तक कि आपकी दाहिनी जांघ जमीन के समानांतर न हो जाए, अपने बाएं घुटने को जमीन से थोड़ा ऊपर रखें।","प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी को धक्का दें।","दूसरी तरफ दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1004', 'Band Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'band', 'strength', 'beginner', '["Stand with your feet shoulder-width apart, with the band placed just above your knees.","Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.","Make sure your knees are tracking over your toes and your weight is in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें और बैंड को अपने घुटनों के ठीक ऊपर रखें।","अपनी छाती को ऊपर और मुख्य भाग को ऊपर रखते हुए, अपने कूल्हों को पीछे धकेलें और अपने घुटनों को मोड़कर स्क्वाट स्थिति में आ जाएँ।","सुनिश्चित करें कि आपके घुटने आपके पैर की उंगलियों पर हों और आपका वजन आपकी एड़ियों पर हो।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Squats_-_With_Bands/0.jpg","Squats_-_With_Bands/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1003', 'Band Squat Row', 'upper legs', 'glutes', '["hamstrings","quadriceps","back"]', 'band', 'strength', NULL, '["Attach the band to a sturdy anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees and lower into a squat position, keeping your back straight and chest lifted.","From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["बैंड को कमर की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए और अपनी बाहों को अपने सामने फैलाकर बैंड के हैंडल को पकड़ें।","अपने घुटनों को मोड़ें और स्क्वाट स्थिति में आ जाएं, अपनी पीठ सीधी रखें और छाती ऊपर उठाएं।","स्क्वाट स्थिति से, अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बैंड के हैंडल को अपने शरीर की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1005', 'Band Standing Crunch', 'waist', 'abs', '["obliques"]', 'band', 'strength', NULL, '["Attach the band to a sturdy anchor point at waist height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["बैंड को कमर की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट से दूर की ओर मुंह करके खड़े हो जाएं।","बैंड को दोनों हाथों से पकड़ें और इसे अपनी छाती तक ले आएं, अपनी कोहनियों को मोड़कर अपने शरीर के करीब रखें।","अपने पेट को संलग्न करें और अपनी छाती को अपने घुटनों की ओर लाते हुए धीरे-धीरे आगे की ओर झुकें।","क्रंच के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1022', 'Band Standing Rear Delt Row', 'shoulders', 'delts', '["trapezius","rhomboids","biceps"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपने पैरों के नीचे रखें।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए और अपनी बाहों को अपने सामने फैलाकर बैंड के हैंडल को पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बैंड को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1007', 'Band Standing Twisting Crunch', 'waist', 'abs', '["obliques"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.","Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.","Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं और बैंड को अपनी ऊपरी पीठ के चारों ओर रखें, इसे अपनी छाती के सामने पार करें।","बैंड के सिरों को अपने हाथों से पकड़ें, अपनी कोहनियों को मोड़कर अपनी भुजाओं के पास रखें।","अपने पेट को संलग्न करें और अपने धड़ को एक तरफ मोड़ें, अपनी कोहनी को विपरीत घुटने की ओर लाएं।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1008', 'Band Step-Up', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'band', 'strength', NULL, '["Place a band around your thighs, just above your knees.","Stand facing a step or platform with your feet hip-width apart.","Step up onto the platform with your right foot, pushing through your heel.","Extend your left leg behind you, keeping it straight.","Lower your left foot back down to the ground.","Repeat with your left foot stepping up onto the platform.","Continue alternating legs for the desired number of repetitions."]', '["अपने घुटनों के ठीक ऊपर, अपनी जाँघों के चारों ओर एक बैंड रखें।","अपने पैरों को कूल्हे की चौड़ाई के बराबर दूरी पर रखते हुए किसी सीढ़ी या मंच की ओर मुंह करके खड़े हो जाएं।","अपने दाहिने पैर के साथ मंच पर कदम रखें, अपनी एड़ी को धक्का देते हुए।","अपने बाएँ पैर को सीधा रखते हुए अपने पीछे फैलाएँ।","अपने बाएँ पैर को वापस ज़मीन पर टिकाएँ।","अपने बाएँ पैर को प्लेटफ़ॉर्म पर आगे बढ़ाते हुए दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1009', 'Band Stiff Leg Deadlift', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and place the band around your ankles.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.","As you lower, push your hips back and allow your knees to bend slightly.","Lower the band towards the ground, feeling a stretch in your hamstrings.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपनी एड़ियों के चारों ओर रखें।","बैंड को दोनों हाथों से अपनी जाँघों के सामने पकड़ें, हथेलियाँ आपके शरीर की ओर।","अपनी पीठ को सीधा और अपने कोर को व्यस्त रखते हुए, कूल्हों पर टिकाएं और धीरे-धीरे अपने ऊपरी शरीर को जमीन की ओर नीचे लाएं।","जैसे ही आप नीचे आते हैं, अपने कूल्हों को पीछे धकेलें और अपने घुटनों को थोड़ा झुकने दें।","अपनी हैमस्ट्रिंग में खिंचाव महसूस करते हुए बैंड को ज़मीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपने ऊपरी शरीर को शुरुआती स्थिति में वापस उठाने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1023', 'Band Straight Back Stiff Leg Deadlift', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and place the band around your upper legs.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.","Feel the stretch in your hamstrings as you lower the band.","Engage your glutes and hamstrings to lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपने ऊपरी पैरों के चारों ओर रखें।","बैंड को दोनों हाथों से अपनी जाँघों के सामने पकड़ें, हथेलियाँ आपके शरीर की ओर।","अपनी पीठ को सीधा रखते हुए और अपने घुटनों को थोड़ा मोड़कर, कूल्हों पर टिकाएं और बैंड को जमीन की ओर नीचे करें।","जैसे ही आप बैंड को नीचे करते हैं, अपनी हैमस्ट्रिंग में खिंचाव महसूस करें।","अपने शरीर को शुरुआती स्थिति में वापस उठाने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1010', 'Band Straight Leg Deadlift', 'back', 'spine', '["hamstrings","glutes"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and place the band around your feet.","Hold the band with both hands, palms facing your body, and keep your arms straight.","Engage your core and maintain a slight bend in your knees.","Slowly hinge forward at your hips, keeping your back straight and chest lifted.","Lower the band towards the ground while keeping your legs straight.","Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपने पैरों के चारों ओर रखें।","बैंड को दोनों हाथों से पकड़ें, हथेलियाँ आपके शरीर की ओर हों, और अपनी भुजाएँ सीधी रखें।","अपने कोर को संलग्न करें और अपने घुटनों को थोड़ा मोड़ें।","अपनी पीठ सीधी और छाती ऊपर उठाते हुए धीरे-धीरे अपने कूल्हों पर आगे की ओर झुकें।","अपने पैरों को सीधा रखते हुए बैंड को ज़मीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर शुरुआती स्थिति में लौटने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1012', 'Band Twisting Overhead Press', 'shoulders', 'delts', '["triceps","upper back"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles at shoulder height with your palms facing forward.","Engage your core and press the band overhead, fully extending your arms.","As you press, twist your torso to one side, keeping your hips stable.","Pause for a moment at the top, then return to the starting position.","Repeat the press and twist on the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपने पैरों के नीचे रखें।","अपनी हथेलियों को आगे की ओर रखते हुए बैंड के हैंडल को कंधे की ऊंचाई पर पकड़ें।","अपने कोर को संलग्न करें और अपनी बाहों को पूरी तरह फैलाते हुए बैंड को ऊपर की ओर दबाएं।","जैसे ही आप दबाते हैं, अपने कूल्हों को स्थिर रखते हुए अपने धड़ को एक तरफ मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","प्रेस को दोहराएं और विपरीत दिशा में मोड़ें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1369', 'Band Two Legs Calf Raise - (Band Under Both Legs) v. 2', 'lower legs', 'calves', '["ankles","feet"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and place a resistance band under both feet.","Hold the ends of the band with your hands for stability.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों पैरों के नीचे एक रेजिस्टेंस बैंड लगाएं।","स्थिरता के लिए बैंड के सिरों को अपने हाथों से पकड़ें।","अपनी पिंडलियों का उपयोग करते हुए अपनी एड़ियों को जमीन से जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1013', 'Band Underhand Pulldown', 'back', 'lats', '["biceps","forearms"]', 'band', 'strength', NULL, '["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Extend your arms fully overhead, keeping your elbows slightly bent.","Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["बैंड को किसी ऊंचे एंकर बिंदु, जैसे पुल-अप बार या मजबूत बीम से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं।","बैंड को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, अपनी बाहों को पूरी तरह ऊपर की ओर फैलाएँ।","अपने लैट्स को संलग्न करें और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए बैंड को अपनी छाती की ओर खींचें।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1014', 'Band V-Up', 'waist', 'abs', '["hip flexors"]', 'band', 'strength', NULL, '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सीधा करके और अपनी बाहों को ऊपर की ओर फैलाकर, बैंड को पकड़कर अपनी पीठ के बल लेट जाएँ।","अपने पेट को शामिल करते हुए, अपने पैरों और शरीर के ऊपरी हिस्से को एक साथ जमीन से ऊपर उठाएं, अपने हाथों को अपने पैर की उंगलियों तक पहुंचाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों और शरीर के ऊपरी हिस्से को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1015', 'Band Vertical Pallof Press', 'waist', 'abs', '["obliques","glutes"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.","Hold the band with both hands and step away from the anchor point, creating tension in the band.","Position yourself perpendicular to the anchor point, with your side facing the band.","Extend your arms straight out in front of you, keeping your hands at chest height.","Engage your core and press the band away from your chest, fully extending your arms.","Hold the position for a few seconds, then slowly bring the band back towards your chest.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को छाती की ऊंचाई पर किसी मजबूत वस्तु के चारों ओर लपेटें।","बैंड को दोनों हाथों से पकड़ें और एंकर पॉइंट से दूर चले जाएं, जिससे बैंड में तनाव पैदा होगा।","अपने आप को एंकर बिंदु पर लंबवत रखें, आपका पक्ष बैंड की ओर हो।","अपनी बाहों को अपने सामने सीधा फैलाएं, अपने हाथों को छाती की ऊंचाई पर रखें।","अपने कोर को संलग्न करें और अपनी बाहों को पूरी तरह फैलाते हुए बैंड को अपनी छाती से दूर दबाएं।","कुछ सेकंड के लिए इसी स्थिति में रहें, फिर धीरे-धीरे बैंड को वापस अपनी छाती की ओर लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1016', 'Band Wrist Curl', 'lower arms', 'forearms', '["biceps","triceps"]', 'band', 'strength', NULL, '["Sit on a bench or chair with your feet flat on the ground.","Hold the band with both hands, palms facing up, and rest your forearms on your thighs.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें।","बैंड को दोनों हाथों से पकड़ें, हथेलियाँ ऊपर की ओर हों और अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, अपने अग्रबाहुओं को निचोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाइयों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1017', 'Band Y-Raise', 'shoulders', 'delts', '["traps","rhomboids"]', 'band', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.","Keep your arms straight and lift them up and out to the sides, forming a ''Y'' shape with your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी हथेलियों को अंदर की ओर रखते हुए बैंड को अपनी जांघों के सामने पकड़ें।","अपनी भुजाओं को सीधा रखें और उन्हें ऊपर और बाहर की ओर उठाएं, जिससे आपके शरीर का ''Y'' आकार बनता है।","आंदोलन के शीर्ष पर अपने कंधे के ब्लेड को एक साथ निचोड़ें।","धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0023', 'Barbell Alternate Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the barbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखते हुए सीधे खड़े हो जाएं और प्रत्येक हाथ में एक बारबेल पकड़ें, हथेलियाँ आगे की ओर हों।","अपनी ऊपरी भुजाओं को स्थिर रखें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ते हुए सांस छोड़ें।","बारबेल्स को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल्स कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","जैसे ही आप धीरे-धीरे बारबेल्स को शुरुआती स्थिति में वापस लाना शुरू करते हैं, श्वास लें।","दोहराव की वांछित संख्या के लिए दोहराएँ, बारी-बारी से हथियार।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0024', 'Barbell Bench Front Squat', 'upper legs', 'quads', '["hamstrings","glutes","calves"]', 'barbell', 'strength', 'expert', '["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.","Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.","Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल आपके कॉलरबोन के ठीक नीचे, आपकी ऊपरी छाती पर टिकी हुई हो।","अपनी कोहनियों को ऊपर और अपनी ऊपरी भुजाओं को ज़मीन के समानांतर रखते हुए, बारबेल को ओवरहैंड ग्रिप से पकड़ें।","घुटनों और कूल्हों पर झुकते हुए, अपनी पीठ को सीधा और अपनी छाती को ऊपर रखते हुए अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","स्क्वाट के निचले हिस्से में एक क्षण के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Front_Barbell_Squat_To_A_Bench/0.jpg","Front_Barbell_Squat_To_A_Bench/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0025', 'Barbell Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'barbell', 'strength', 'beginner', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ के साथ पकड़ें।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर पकड़ें।","अपनी कोहनियों को अंदर की ओर रखते हुए बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएँ।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को फैलाकर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Bench_Press_-_Medium_Grip/0.jpg","Barbell_Bench_Press_-_Medium_Grip/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-0026', 'Barbell Bench Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'barbell', 'strength', 'expert', '["Set up a barbell on a squat rack at chest height.","Stand facing away from the rack, with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.","Lower your body down into a squat, keeping your knees in line with your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["छाती की ऊंचाई पर स्क्वाट रैक पर बारबेल स्थापित करें।","अपने पैरों को कंधे की चौड़ाई की दूरी पर रखते हुए, रैक से दूर की ओर मुंह करके खड़े हो जाएं।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएं, अपनी पीठ सीधी और छाती ऊपर रखें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को रैक से उठाएं और पीछे हटें, यह सुनिश्चित करते हुए कि आपके पैर अभी भी कंधे की चौड़ाई से अलग हैं।","अपने घुटनों को अपने पैर की उंगलियों के अनुरूप रखते हुए, अपने शरीर को स्क्वाट में नीचे झुकाएँ।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Squat_To_A_Bench/0.jpg","Barbell_Squat_To_A_Bench/1.jpg"]', 5, 'sets', 0, 'opengym', 1)
ON CONFLICT(id) DO UPDATE SET name=excluded.name, body_part=excluded.body_part, target=excluded.target, secondary=excluded.secondary, equipment=excluded.equipment, category=excluded.category, level=excluded.level, instructions=excluded.instructions, instructions_hi=excluded.instructions_hi, images=excluded.images, met=excluded.met, tracking=excluded.tracking, popular=excluded.popular, source=excluded.source, active=excluded.active WHERE exercises.edited=0;
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1316', 'Barbell Bent Arm Pullover', 'back', 'lats', '["triceps","chest"]', 'barbell', 'strength', 'intermediate', '["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Lower the barbell behind your head while keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने सिर को एक छोर पर और अपने पैरों को फर्श पर रखकर सीधे लेट जाएं।","कंधे की चौड़ाई की पकड़ के साथ बारबेल को पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएं।","अपनी बाहों को थोड़ा झुकाते हुए बारबेल को अपने सिर के पीछे नीचे करें।","एक पल के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Bent-Arm_Barbell_Pullover/0.jpg","Bent-Arm_Barbell_Pullover/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0027', 'Barbell Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'barbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the hips while keeping your back straight and chest up.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपने कंधे के ब्लेड को पीछे खींचकर और अपनी पीठ की मांसपेशियों को निचोड़कर बारबेल को अपनी निचली छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Bent_Over_Barbell_Row/0.jpg","Bent_Over_Barbell_Row/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-2407', 'Barbell Biceps Curl (With Arm Blaster)', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping your elbows close to your torso.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और हथेलियां ऊपर की ओर रखते हुए बारबेल को हाथ से पकड़ें।","अपनी कोहनियों को अपने धड़ के पास रखते हुए, अपनी ऊपरी भुजाओं को आर्म ब्लास्टर के सामने रखें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0028', 'Barbell Clean And Press', 'upper legs', 'quads', '["hamstrings","glutes","shoulders","triceps"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and the barbell on the floor in front of you.","Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.","As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.","As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.","From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल आपके सामने फर्श पर हो।","अपने घुटनों को मोड़ें और कूल्हों पर टिकाकर नीचे की ओर झुकें और बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी एड़ी के माध्यम से ड्राइव करें और बारबेल को अपने शरीर के करीब रखते हुए, फर्श से उठाने के लिए अपने कूल्हों और घुटनों का विस्तार करें।","जैसे ही बारबेल आपकी जांघों तक पहुंचे, अपने कूल्हों को तेजी से फैलाएं, अपने कंधों को सिकोड़ें और बारबेल को अपनी छाती की ओर ऊपर खींचें।","जैसे ही बारबेल छाती की ऊंचाई तक पहुंचती है, तुरंत इसके नीचे झुकें और इसे कंधे के स्तर पर पकड़ें, आपकी कोहनी आगे की ओर और आपकी हथेलियाँ ऊपर की ओर हों।","पकड़ने की स्थिति से, अपनी बाहों को फैलाकर बारबेल को ऊपर की ओर दबाएं और बारबेल को सीधा ऊपर की ओर धकेलें।","बारबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0029', 'Barbell Clean-Grip Front Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'barbell', 'strength', NULL, '["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.","Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.","Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके और बारबेल को अपनी ऊपरी छाती पर टिकाकर, अपनी कोहनियों को आगे की ओर रखते हुए खड़े होकर शुरुआत करें।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को नीचे लाएँ, जैसे कि आप किसी कुर्सी पर पीछे बैठे हों।","नीचे उतरते समय अपनी छाती को ऊपर और अपनी पीठ को सीधा रखें, यह सुनिश्चित करें कि आपके घुटने आपके पैर की उंगलियों से आगे न जाएं।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","एक पल के लिए नीचे रुकें, फिर अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0030', 'Barbell Close-Grip Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', 'beginner', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक संकीर्ण पकड़ के साथ पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Close-Grip_Barbell_Bench_Press/0.jpg","Close-Grip_Barbell_Bench_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0031', 'Barbell Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', 'beginner', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the bar back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और हथेलियां आगे की ओर रखते हुए बारबेल को हाथ से पकड़ें।","अपनी कोहनियों को अपने धड़ के पास रखें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ते हुए सांस छोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बार कंधे के स्तर पर न आ जाए, तब तक बार को ऊपर उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","जैसे ही आप धीरे-धीरे बार को प्रारंभिक स्थिति में वापस लाना शुरू करते हैं, श्वास लें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Curl/0.jpg","Barbell_Curl/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-0032', 'Barbell Deadlift', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'barbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As you stand up straight, squeeze your glutes and keep your core engaged.","Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल आपके सामने जमीन पर हो।","अपने घुटनों को मोड़ें और अपने धड़ को नीचे करने के लिए कूल्हों पर टिकाएं और बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","बारबेल को जमीन से ऊपर उठाने के लिए अपनी एड़ी के माध्यम से ड्राइव करते समय अपनी पीठ सीधी और छाती ऊपर रखें, अपने कूल्हों और घुटनों को फैलाएं।","जैसे ही आप सीधे खड़े हों, अपने ग्लूट्स को निचोड़ें और अपने कोर को व्यस्त रखें।","अपनी पीठ को सीधा रखते हुए, कूल्हों और घुटनों पर झुकते हुए बारबेल को वापस ज़मीन पर नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Deadlift/0.jpg","Barbell_Deadlift/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-0033', 'Barbell Decline Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'barbell', 'strength', 'beginner', '["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सुरक्षित रखते हुए और अपने सिर को अपने कूल्हों से नीचे करके एक डिक्लाइन बेंच पर लेटें।","बारबेल को कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ के साथ पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Decline_Barbell_Bench_Press/0.jpg","Decline_Barbell_Bench_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0034', 'Barbell Decline Bent Arm Pullover', 'back', 'lats', '["triceps","chest"]', 'barbell', 'strength', NULL, '["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position by contracting your lats.","Repeat for the desired number of repetitions."]', '["अपने सिर को अपने कूल्हों से नीचे और अपने पैरों को सुरक्षित रखते हुए एक डिक्लाइन बेंच पर लेट जाएँ।","एक बारबेल को उभरी हुई पकड़ से पकड़ें (हथेलियाँ आपसे दूर की ओर हों) और अपनी भुजाओं को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी भुजाओं को थोड़ा मुड़ा हुआ रखते हुए बारबेल को अपने सिर के पीछे नियंत्रित तरीके से नीचे लाएँ।","एक पल के लिए रुकें, फिर अपने लैट्स को सिकोड़कर बारबेल को शुरुआती स्थिति में वापस उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0035', 'Barbell Decline Close Grip To Skull Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', NULL, '["Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.","Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms to press the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने सिर को अपने पैरों से नीचे करके एक डिक्लाइन बेंच पर लेटें और बारबेल को कसकर पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर बारबेल को अपने माथे की ओर नीचे करें।","एक पल के लिए रुकें, फिर अपनी बाहों को फैलाकर बारबेल को वापस प्रारंभिक स्थिति में दबाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1255', 'Barbell Decline Pullover', 'chest', 'pectorals', '["triceps","shoulders"]', 'barbell', 'strength', NULL, '["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.","Extend your arms above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.","Pause for a moment, then return the barbell to the starting position by reversing the motion.","Repeat for the desired number of repetitions."]', '["अपने सिर को अपने कूल्हों से नीचे और अपने पैरों को सुरक्षित रखते हुए एक डिक्लाइन बेंच पर लेट जाएँ।","बारबेल को एक उभरी हुई पकड़ से पकड़ें (हथेलियाँ आपसे दूर की ओर हों) और आपके हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी बाहों को अपनी छाती के ऊपर फैलाएँ।","अपनी छाती और कंधों में खिंचाव महसूस करते हुए बारबेल को अपने सिर के पीछे चाप की गति में नीचे करें।","एक पल के लिए रुकें, फिर गति को उलट कर बारबेल को शुरुआती स्थिति में लौटा दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0036', 'Barbell Decline Wide-Grip Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'barbell', 'strength', NULL, '["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows out to the sides.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सुरक्षित रखते हुए और अपने सिर को अपने कूल्हों से नीचे करके एक डिक्लाइन बेंच पर लेटें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़ी पकड़ से पकड़ें।","अपनी कोहनियों को बगल की ओर रखते हुए, बारबेल को अपनी छाती तक नीचे लाएँ।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0037', 'Barbell Decline Wide-Grip Pullover', 'back', 'lats', '["triceps","chest"]', 'barbell', 'strength', 'intermediate', '["Lie on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a wide grip and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms straight.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने सिर को अपने कूल्हों से नीचे और अपने पैरों को सुरक्षित रखते हुए एक डिक्लाइन बेंच पर लेटें।","एक बारबेल को चौड़ी पकड़ से पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी भुजाओं को सीधा रखते हुए बारबेल को अपने सिर के पीछे नियंत्रित तरीके से नीचे लाएँ।","एक पल के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Wide-Grip_Decline_Barbell_Pullover/0.jpg","Wide-Grip_Decline_Barbell_Pullover/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0038', 'Barbell Drag Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Let the barbell hang at arm''s length in front of your thighs.","Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और हथेलियाँ ऊपर की ओर रखते हुए बारबेल को हाथ से पकड़ें।","बारबेल को अपनी जांघों के सामने एक हाथ की दूरी पर लटका रहने दें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपने बाइसेप्स को सिकोड़कर बारबेल को अपनी छाती की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1370', 'Barbell Floor Calf Raise', 'lower legs', 'calves', '["hamstrings"]', 'barbell', 'strength', NULL, '["Place a barbell on the floor in front of you.","Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.","Hold onto a stable object for balance if needed.","Raise your heels as high as possible, using your calves to lift your body.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने सामने फर्श पर एक बारबेल रखें।","अपने पैरों की उंगलियों को बारबेल के किनारे पर रखते हुए, अपनी एड़ियों को लटकाकर खड़े रहें।","यदि आवश्यक हो तो संतुलन के लिए किसी स्थिर वस्तु को पकड़ें।","अपने शरीर को ऊपर उठाने के लिए अपनी पिंडलियों का उपयोग करते हुए, अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0039', 'Barbell Front Chest Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'barbell', 'strength', NULL, '["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े होकर शुरुआत करें, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","अपने हाथों को कंधे की चौड़ाई पर, कोहनियों को आगे की ओर रखते हुए, बारबेल को अपनी छाती के सामने पकड़ें।","अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें क्योंकि आप अपने शरीर को स्क्वाट स्थिति में नीचे लाते हैं, अपने कूल्हों को पीछे धकेलते हैं और अपने घुटनों को मोड़ते हैं।","तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0041', 'Barbell Front Raise', 'shoulders', 'delts', '["biceps","triceps"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी जांघों के सामने एक बारबेल को ज़ोर से पकड़ें।","अपनी भुजाओं को सीधा रखें और बारबेल को कंधे के स्तर तक पहुंचने तक आगे और ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0040', 'Barbell Front Raise And Pullover', 'chest', 'pectorals', '["deltoids","triceps"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Next, lower the barbell behind your head, keeping your arms straight.","Pause for a moment at the bottom, then raise the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और हथेलियां नीचे की ओर रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी भुजाएं सीधी रखें और बारबेल को अपने सामने तब तक उठाएं जब तक यह कंधे की ऊंचाई तक न पहुंच जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","इसके बाद, अपनी बाहों को सीधा रखते हुए बारबेल को अपने सिर के पीछे नीचे करें।","नीचे एक पल के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0042', 'Barbell Front Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'barbell', 'strength', 'expert', '["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े होकर शुरुआत करें, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपने कंधों के सामने पकड़ें, इसे अपने कॉलरबोन और कंधों पर टिकाएं।","अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें क्योंकि आप अपने शरीर को स्क्वाट स्थिति में नीचे लाते हैं, अपने कूल्हों को पीछे धकेलते हैं और अपने घुटनों को मोड़ते हैं।","तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Front_Barbell_Squat/0.jpg","Front_Barbell_Squat/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0043', 'Barbell Full Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'barbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower yourself until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल या पीछे के डेल्टा पर टिकाएं।","जब आप अपने शरीर को नीचे करना शुरू करें तो अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें।","घुटनों और कूल्हों पर झुकें, अपने कूल्हों को पीछे और नीचे धकेलें जैसे कि कुर्सी पर बैठे हों।","अपने आप को तब तक नीचे रखें जब तक आपकी जांघें ज़मीन के समानांतर या थोड़ा नीचे न हो जाएं।","अपने घुटनों को अपने पंजों की सीध में रखें और अपना वजन अपनी एड़ियों पर रखें।","अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ी से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Full_Squat/0.jpg","Barbell_Full_Squat/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-1461', 'Barbell Full Squat (Back Pov)', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल या पीछे के डेल्टा पर टिकाएं।","जब आप अपने शरीर को नीचे करना शुरू करें तो अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें।","घुटनों और कूल्हों पर झुकें, अपने कूल्हों को पीछे और नीचे धकेलें जैसे कि कुर्सी पर बैठे हों।","अपने शरीर को तब तक नीचे झुकाएँ जब तक कि आपकी जाँघें ज़मीन के समानांतर या थोड़ा नीचे न आ जाएँ।","अपने घुटनों को अपने पंजों की सीध में रखें और अपना वजन अपनी एड़ियों पर रखें।","अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ी से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1462', 'Barbell Full Squat (Side Pov)', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल या पीछे के डेल्टा पर टिकाएं।","जब आप अपने शरीर को नीचे करना शुरू करें तो अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें।","घुटनों और कूल्हों पर झुकें, अपने कूल्हों को पीछे और नीचे धकेलें जैसे कि कुर्सी पर बैठे हों।","अपने शरीर को तब तक नीचे झुकाएँ जब तक कि आपकी जाँघें ज़मीन के समानांतर या थोड़ा नीचे न आ जाएँ।","अपने घुटनों को अपने पंजों की सीध में रखें और अपना वजन अपनी एड़ियों पर रखें।","अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ी से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1545', 'Barbell Full Zercher Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top of the movement.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पंजों को थोड़ा बाहर की ओर करके खड़े हो जाएं।","स्थिरता के लिए बारबेल को अपनी कोहनियों के मोड़ से पकड़ें, अपने हाथों से बारबेल को पकड़ें।","अपने कोर को संलग्न करें और अपने कूल्हों को पीछे की ओर झुकाते हुए स्क्वाट स्थिति में आते समय अपनी छाती को ऊपर उठाएं।","अपने घुटनों को अपने पंजों की सीध में रखें और अपना वजन अपनी एड़ियों पर रखें।","तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें।","वापस खड़े होने के लिए अपनी एड़ियों के माध्यम से ड्राइव करें, आंदोलन के शीर्ष पर अपने ग्लूट्स को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1409', 'Barbell Glute Bridge', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'barbell', 'strength', 'intermediate', '["Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को फर्श पर सपाट रखते हुए, अपनी पीठ के बल जमीन पर लेटकर शुरुआत करें।","अपने कूल्हों पर एक बारबेल रखें, इसे दोनों हाथों से सुरक्षित रूप से पकड़ें।","अपने ग्लूट्स और कोर की मांसपेशियों को शामिल करें, फिर अपने कूल्हों को ज़मीन से ऊपर उठाएं जब तक कि आपका शरीर आपके घुटनों से आपके कंधों तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, अपने ग्लूट्स को निचोड़ें।","धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Glute_Bridge/0.jpg","Barbell_Glute_Bridge/1.jpg"]', 5, 'sets', 0, 'opengym', 1)
ON CONFLICT(id) DO UPDATE SET name=excluded.name, body_part=excluded.body_part, target=excluded.target, secondary=excluded.secondary, equipment=excluded.equipment, category=excluded.category, level=excluded.level, instructions=excluded.instructions, instructions_hi=excluded.instructions_hi, images=excluded.images, met=excluded.met, tracking=excluded.tracking, popular=excluded.popular, source=excluded.source, active=excluded.active WHERE exercises.edited=0;
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-3562', 'Barbell Glute Bridge Two Legs On Bench (Male)', 'upper legs', 'glutes', '["hamstrings","core"]', 'barbell', 'strength', NULL, '["Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच के किनारे पर अपनी ऊपरी पीठ को टिकाकर और अपने पैरों को ज़मीन पर सपाट, कूल्हे की चौड़ाई के बराबर दूरी पर रखकर शुरुआत करें।","अपने कूल्हों पर एक बारबेल रखें, इसे दोनों हाथों से सुरक्षित रूप से पकड़ें।","अपने ग्लूट्स और कोर की मांसपेशियों को शामिल करें, फिर अपने कूल्हों को बेंच से ऊपर उठाने के लिए अपनी एड़ी पर दबाव डालें, जिससे आपके घुटनों से लेकर आपके कंधों तक एक सीधी रेखा बन जाए।","शीर्ष पर एक पल के लिए रुकें, अपने ग्लूट्स को निचोड़ें।","धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0044', 'Barbell Good Morning', 'upper legs', 'hamstrings', '["lower back"]', 'barbell', 'strength', NULL, '["Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और बारबेल को अपनी पीठ के ऊपरी हिस्से पर टिकाकर खड़े होकर शुरुआत करें।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए, कूल्हों पर आगे की ओर झुकें, अपने नितंबों को पीछे धकेलें जैसे कि आप अपने ग्लूट्स से अपने पीछे की दीवार को छूने की कोशिश कर रहे हों।","अपने धड़ को तब तक नीचे करें जब तक वह ज़मीन के समानांतर न हो जाए, अपनी हैमस्ट्रिंग में खिंचाव महसूस करें।","एक पल के लिए रुकें, फिर अपने ग्लूट्स को निचोड़ते हुए और अपने कूल्हों को आगे की ओर धकेलते हुए प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0045', 'Barbell Guillotine Bench Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'barbell', 'strength', 'intermediate', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.","Pause for a moment when the barbell is just above your neck.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपनी कोहनियों को बाहर की ओर रखते हुए बारबेल को धीरे-धीरे अपनी गर्दन की ओर नीचे लाएं।","जब बारबेल आपकी गर्दन के ठीक ऊपर हो तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Guillotine_Bench_Press/0.jpg","Barbell_Guillotine_Bench_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0046', 'Barbell Hack Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', 'intermediate', '["Start by standing with your feet shoulder-width apart and your toes slightly turned out.","Hold the barbell behind your legs, resting it on your upper thighs.","Lower your body by bending at the knees and hips, keeping your back straight and your chest up.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और अपने पैर की उंगलियों को थोड़ा बाहर की ओर करके खड़े होकर शुरुआत करें।","बारबेल को अपने पैरों के पीछे पकड़ें, इसे अपनी ऊपरी जांघों पर टिकाएं।","घुटनों और कूल्हों को मोड़कर अपने शरीर को नीचे लाएँ, अपनी पीठ सीधी रखें और अपनी छाती ऊपर रखें।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Hack_Squat/0.jpg","Barbell_Hack_Squat/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1436', 'Barbell High Bar Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell on your upper back, resting it on your traps.","Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपनी ऊपरी पीठ पर रखें, इसे अपने जाल पर टिकाएं।","जब आप बैठना शुरू करें तो अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें, अपने कूल्हों को पीछे धकेलें और अपने घुटनों को मोड़ें।","अपने आप को तब तक नीचे करें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या जितना नीचे आप आराम से जा सकें।","अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ी से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0047', 'Barbell Incline Bench Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'barbell', 'strength', 'beginner', '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपने पैरों को ज़मीन पर सपाट करके बेंच पर लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को 45 डिग्री के कोण पर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1719', 'Barbell Incline Close Grip Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपने पैरों को ज़मीन पर सपाट करके बेंच पर लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक संकीर्ण पकड़ के साथ पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0048', 'Barbell Incline Reverse-Grip Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच पर पीठ के बल लेट जाएं और बारबेल को उल्टी पकड़ से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे अपनी ऊपरी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0049', 'Barbell Incline Row', 'back', 'upper back', '["biceps","forearms"]', 'barbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest against the pad and your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपनी छाती को पैड से सटाकर और अपने पैरों को ज़मीन पर सपाट रखते हुए बेंच पर मुँह के बल लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0050', 'Barbell Incline Shoulder Raise', 'chest', 'serratus anterior', '["deltoids","trapezius"]', 'barbell', 'strength', 'beginner', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell up to shoulder height, keeping your elbows slightly bent.","Slowly raise the barbell overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच पर अपनी पीठ पैड से सटाकर और पैरों को ज़मीन पर सपाट करके बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़ी पकड़ के साथ पकड़ें।","अपनी कोहनियों को थोड़ा मोड़ते हुए बारबेल को कंधे की ऊंचाई तक उठाएं।","अपनी भुजाओं को पूरी तरह फैलाते हुए धीरे-धीरे बारबेल को ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस कंधे की ऊंचाई तक नीचे लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Incline_Shoulder_Raise/0.jpg","Barbell_Incline_Shoulder_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0051', 'Barbell Jefferson Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.","Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Push through your heels to stand back up to the starting position.","Repeat the movement, alternating your forward and back foot with each repetition."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पंजों को थोड़ा बाहर की ओर करके खड़े हो जाएं।","बारबेल को ऊपरी पकड़ से पकड़ें, इसे अपने शरीर के सामने, अपनी कमर के ठीक नीचे रखें।","अपने बाएं पैर को आगे और अपने दाहिने पैर को पीछे ले जाएं, अपने पैरों को कंधे की चौड़ाई से अलग रखें।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएं, अपनी पीठ सीधी और छाती ऊपर रखें।","प्रारंभिक स्थिति में वापस खड़े होने के लिए अपनी एड़ियों को धक्का दें।","प्रत्येक दोहराव के साथ अपने आगे और पीछे के पैर को बारी-बारी से दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0052', 'Barbell Jm Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, बारबेल को अपनी छाती तक नीचे लाएँ।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0053', 'Barbell Jump Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Once you reach the bottom of the squat, explode upwards by jumping off the ground.","As you jump, extend your hips, knees, and ankles, pushing through your toes.","Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर, अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़कर खड़े होकर शुरुआत करें।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ।","एक बार जब आप स्क्वाट के निचले भाग पर पहुंच जाएं, तो जमीन से कूदकर ऊपर की ओर विस्फोट करें।","जैसे ही आप कूदते हैं, अपने पैर की उंगलियों से धक्का देते हुए अपने कूल्हों, घुटनों और टखनों को फैलाएं।","धीरे से वापस स्क्वाट स्थिति में आ जाएँ और वांछित संख्या में दोहराव के लिए तुरंत इस क्रिया को दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1410', 'Barbell Lateral Lunge', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.","Push off with your right foot and return to the starting position.","Repeat on the other side, stepping with your left foot."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़ें।","अपने दाहिने पैर को बगल में रखते हुए एक बड़ा कदम उठाएं, अपने बाएं पैर को सीधा रखें।","अपने दाहिने घुटने को मोड़ें और अपने शरीर को नीचे झुकाकर स्थिति में लाएँ, अपने बाएँ पैर को सीधा रखें।","अपने दाहिने पैर से धक्का दें और प्रारंभिक स्थिति में लौट आएं।","अपने बाएं पैर से कदम बढ़ाते हुए दूसरी तरफ भी दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1435', 'Barbell Low Bar Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल आपकी पीठ के ऊपरी हिस्से पर टिका हो।","अपनी छाती को ऊपर और कोर को व्यस्त रखते हुए, अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए धीरे-धीरे अपने शरीर को नीचे लाएँ।","जब तक आपकी जांघें जमीन के समानांतर या थोड़ा नीचे न हो जाएं तब तक नीचे करना जारी रखें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0054', 'Barbell Lunge', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', 'intermediate', '["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step forward with your right foot, keeping your torso upright.","Lower your body by bending your right knee until your thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg, alternating legs for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और एक बारबेल को अपनी पीठ के ऊपरी हिस्से पर टिकाकर खड़े होकर शुरुआत करें।","अपने धड़ को सीधा रखते हुए अपने दाहिने पैर से एक कदम आगे बढ़ाएं।","अपने दाहिने घुटने को मोड़कर अपने शरीर को नीचे करें जब तक कि आपकी जांघ जमीन के समानांतर न हो जाए।","प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी को धक्का दें।","वांछित संख्या में दोहराव के लिए पैरों को बारी-बारी से अपने बाएं पैर से दोहराएं।"]', '["Barbell_Lunge/0.jpg","Barbell_Lunge/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1720', 'Barbell Lying Back Of The Head Tricep Extension', 'upper arms', 'triceps', '["shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें, और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0055', 'Barbell Lying Close-Grip Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को ज़ोर से पकड़ें, हाथ कंधे की चौड़ाई पर अलग हों, हथेलियाँ आपके पैरों की ओर हों।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर पकड़ें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएं।","जब बारबेल आपकी छाती को छू ले तो एक पल के लिए रुकें, फिर उसे वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0056', 'Barbell Lying Close-Grip Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.","Extend your arms fully, lifting the barbell above your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को कसकर पकड़ें, हाथ कंधे की चौड़ाई पर अलग हों, हथेलियाँ ऊपर की ओर हों।","अपनी बाहों को पूरी तरह फैलाएं, बारबेल को अपनी छाती से ऊपर उठाएं।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने माथे की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0057', 'Barbell Lying Extension', 'upper arms', 'triceps', '["shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को ऊपरी पकड़ से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें, और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने माथे की ओर नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0058', 'Barbell Lying Lifting (On Hip)', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'barbell', 'strength', NULL, '["Lie flat on your back on a bench with your feet flat on the ground and your knees bent.","Hold the barbell with an overhand grip and position it on your hips.","Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपनी पीठ के बल लेट जाएं और आपके पैर जमीन पर सपाट हों और आपके घुटने मुड़े हुए हों।","बारबेल को ओवरहैंड ग्रिप से पकड़ें और इसे अपने कूल्हों पर रखें।","अपने ग्लूट्स को जोड़ते हुए, अपने कूल्हों को बेंच से ऊपर उठाएं जब तक कि आपका शरीर आपके घुटनों से आपके कंधों तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0059', 'Barbell Lying Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', NULL, '["Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["एक उपदेशक बेंच पर अपनी छाती को पैड से सटाकर और अपनी बाहों को किनारे पर फैलाकर, एक बारबेल को अंडरहैंड ग्रिप से पकड़कर बैठें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बार कंधे के स्तर पर न आ जाए, तब तक बार को ऊपर उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0061', 'Barbell Lying Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को ऊपरी पकड़ से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें, और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने माथे की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0060', 'Barbell Lying Triceps Extension Skull Crusher', 'upper arms', 'triceps', '["shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को ऊपरी पकड़ से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें, और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने माथे की ओर नीचे करें।","जब बारबेल आपके माथे के ठीक ऊपर हो तो एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0063', 'Barbell Narrow Stance Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पैरों की उंगलियों को थोड़ा बाहर की ओर करके खड़े रहें।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल या पीछे के डेल्टा पर टिकाएं।","अपने कोर को संलग्न करें और अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए धीरे-धीरे अपने शरीर को नीचे लाते हुए अपनी छाती को ऊपर रखें।","जब तक आपकी जांघें जमीन के समानांतर या थोड़ा नीचे न हो जाएं तब तक नीचे करना जारी रखें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
ON CONFLICT(id) DO UPDATE SET name=excluded.name, body_part=excluded.body_part, target=excluded.target, secondary=excluded.secondary, equipment=excluded.equipment, category=excluded.category, level=excluded.level, instructions=excluded.instructions, instructions_hi=excluded.instructions_hi, images=excluded.images, met=excluded.met, tracking=excluded.tracking, popular=excluded.popular, source=excluded.source, active=excluded.active WHERE exercises.edited=0;